reference_solution:
def kth_lexical_number(n, k):
    prefix,remaining = 1,k-1
    while remaining:
        low,high,count = prefix,prefix+1,0
        while low<=n:
            count += min(n+1,high)-low
            low,high = low*10,high*10
        if count<=remaining:
            prefix += 1
            remaining -= count
        else:
            prefix *= 10
            remaining -= 1
    return prefix

